set -eu
test "$(git rev-parse HEAD)" = 2141d6f41816f70997df42b54bcc85b2c72a92c8
command -v adb >/dev/null
adb start-server >/dev/null
python3 - <<'PY'
import os, subprocess
def adb(*args):
    return subprocess.run(["adb", *args], capture_output=True, text=True, timeout=25)
result = adb("devices", "-l")
if result.returncode:
    raise SystemExit("ADB_DEVICE_LIST_ERROR: "+result.stderr[:200])
entries = []
for line in result.stdout.splitlines()[1:]:
    parts = line.split()
    if len(parts) < 2: continue
    serial, state = parts[:2]
    props = parts[2:]
    if state == "device" and any(x.startswith("usb:") for x in props):
        entries.append(serial)
    elif state == "device" and ":" not in serial and not serial.startswith("emulator-"):
        entries.append(serial)
print("ADB_USB_AUTHORIZED_COUNT", len(entries))
if len(entries) != 1:
    print("ADB_STATES_ONLY", [line.split()[1] for line in result.stdout.splitlines()[1:] if len(line.split()) >= 2])
    raise SystemExit("EXPECTED_EXACTLY_ONE_AUTHORIZED_USB_DEVICE")
serial = entries[0]
def safe_shell(*args):
    p=adb("-s",serial,"shell",*args)
    if p.returncode: raise SystemExit("ADB_SHELL_FAILED")
    return p.stdout.strip()
model=safe_shell("getprop","ro.product.model")
release=safe_shell("getprop","ro.build.version.release")
print("ADB_MODEL",model)
print("ADB_ANDROID_VERSION",release)
if model!="SM-S906B": raise SystemExit("WRONG_USB_MODEL")
package=safe_shell("pm","path","io.blueeye")
print("BLUEEYE_PREVIOUSLY_INSTALLED", package.startswith("package:"))
print("EXACT_SOURCE_SHA", "2141d6f41816f70997df42b54bcc85b2c72a92c8")
apk="app/build/outputs/apk/debug/app-debug.apk"
print("LOCAL_DEBUG_APK_EXISTS", os.path.isfile(apk))
if os.path.isfile(apk): print("LOCAL_DEBUG_APK_SIZE_BYTES",os.path.getsize(apk))
print("ADB_PREFLIGHT_OK")
PY
